def _set_parent(self, parent=None):
        """
        Set parent.

        :param parent: Parentable object.
        :raises ValueError: Self-reference object passed.
        :raises ValueError: Non-Parentable object passed.
        """
        if parent is None:
            self._parent = None
        elif isinstance(parent, Parentable):
            if parent is self:
                raise ValueError('Self-reference object passed.')
            self._parent = parent
        else:
            raise ValueError('Non-Parentable object passed.')

